//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::pop`; the
//! native twin is `benches/native/Bench/ArrayPop.lean`.
//! the array is updated in place on both sides (Lean's is unique after its first copy of the
//! input, the Rust twin's a copy made once); each iteration pops and pushes one element

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<u64>, n: u64) -> u64 {
    let xs = &inp[..];
    let mut st = inp.clone();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        if let Some(k) = array::pop(st.len()) {
            st.truncate(k);
        }
        st.push(nat_box(x >> 40));
        acc = mix(acc, nat_unbox(get_word(&st, (x >> 40) & 4095)));
    }
    acc
}

fn main() {
    run(|| nat_words(), kernel)
}
